<?php $id=(int)($_SESSION['booking_id']??0);$ref=$_SESSION['booking_ref']??'';$q=db()->prepare('SELECT b.*,p.full_name,t.depart_at,t.arrive_at,r.train_code,a.name origin,c.name destination,GROUP_CONCAT(bs.seat_code ORDER BY bs.seat_code SEPARATOR ", ") seats FROM bookings b JOIN passengers p ON p.booking_id=b.id JOIN trips t ON t.id=b.trip_id JOIN routes r ON r.id=t.route_id JOIN stations a ON a.id=r.from_station_id JOIN stations c ON c.id=r.to_station_id JOIN booking_seats bs ON bs.booking_id=b.id WHERE b.id=? AND b.email=? GROUP BY b.id');$q->execute([$id,$_SESSION['booking_email']??'']);$b=$q->fetch(); ?>
<?php if(!$b): ?><section class="container content-section"><div class="empty-state"><h2>Booking not found</h2><a class="button primary" href="?page=manage">Look up a booking</a></div></section><?php else: ?><section class="confirmation-wrap"><div class="container"><div class="success-mark">✓</div><p class="eyebrow">BOOKING CONFIRMED · DEMO</p><h1>Your journey is <em>on its way.</em></h1><p class="muted">A sample e-ticket is ready. Keep the booking reference for later.</p><article class="ticket-card"><div class="ticket-head"><span>CRS RAILWAY · E-TICKET</span><span class="pill green"><?= h($b['status']) ?></span></div><div class="ticket-ref"><small>BOOKING REFERENCE</small><strong><?= h($b['reference']) ?></strong></div><div class="ticket-route"><div><small>FROM</small><strong><?= h($b['origin']) ?></strong><b><?= h(date('H:i',strtotime($b['depart_at']))) ?></b></div><span>────────→</span><div><small>TO</small><strong><?= h($b['destination']) ?></strong><b><?= h(date('H:i',strtotime($b['arrive_at']))) ?></b></div></div><div class="ticket-details"><span>Passenger<strong><?= h($b['full_name']) ?></strong></span><span>Train<strong><?= h($b['train_code']) ?></strong></span><span>Seat(s)<strong><?= h($b['seats']) ?></strong></span><span>Total fare<strong><?= money((float)$b['total_fare']) ?></strong></span></div><div class="ticket-foot">Payment is simulated for this coursework demo.</div></article><div class="center-actions"><a class="button primary" href="?download=<?= (int)$b['id'] ?>">Download e-ticket ↓</a><a class="button secondary" href="?page=tickets">My tickets</a></div></div></section><?php endif; ?>
